-- compatibility: breaking
-- Unknown historical review authority requires human revision and review.
DROP TRIGGER require_firm_authority_export;
CREATE TRIGGER require_firm_authority_export BEFORE UPDATE ON drafts WHEN OLD.status='approved' AND NEW.status='exported' AND NOT EXISTS(SELECT 1 FROM review_authority_snapshots WHERE proof_kind='review_time' AND subject_kind='draft' AND subject_id=NEW.id AND reviewed_version=OLD.version-1 AND book_id=NEW.book_id) BEGIN SELECT RAISE(ABORT,'Historical review requires firm verification'); END;
DROP TRIGGER require_firm_authority_voucher;
CREATE TRIGGER require_firm_authority_voucher BEFORE INSERT ON vouchers WHEN NOT EXISTS(SELECT 1 FROM review_authority_snapshots s WHERE s.proof_kind='review_time' AND s.book_id=NEW.book_id AND (s.subject_kind='draft' AND NEW.source_kind='draft' AND NEW.periodic_review_id IS NULL AND s.subject_id=NEW.source_id AND s.reviewed_version=(SELECT CASE WHEN d.status='exported' THEN d.version-2 ELSE d.version-1 END FROM drafts d WHERE d.id=NEW.source_id) OR s.subject_kind='manual' AND s.subject_id=NEW.review_request_id AND s.reviewed_version=(SELECT version FROM manual_review_requests WHERE id=NEW.review_request_id) OR s.subject_kind='periodic' AND s.subject_id=NEW.periodic_review_id AND s.reviewed_version=(SELECT version FROM periodic_drafts WHERE id=NEW.periodic_review_id))) BEGIN SELECT RAISE(ABORT,'Firm review proof required'); END;
